relp(){ local r="${1#.}" d="$PWD" n f s segs i;[[ "$r" == */* ]]&&{ n="${r##*/}";f="${r%/*}";}||{ n="$r";f="";};IFS=/ read -ra segs<<<"$f";for s in "${segs[@]}";do [ -z "$s" ]&&continue;if [ -z "${s//-/}" ];then for((i=0;i<${#s};i++));do d=${d%/*};d=${d:-/};done;else d="$d/$s";fi;done;if [ -z "$n" ];then [ -d "$d" ]&&echo "$d"||return 1;elif [[ "$n" == *.* || -f "$d/$n" ]];then [ -f "$d/$n" ]&&echo "$d/$n"||return 1;else local m;for m in "$d/$n".*;do [ -f "$m" ]&&{ echo "$m";return 0;};done;return 1;fi;}
